insert into public.curriculum_weeks (week_no, level, theme, goal) values
(1, 'A1', 'Sounds, alphabet, farewells', 'Read the alphabet aloud and say hello/goodbye confidently.'),
(2, 'A1', 'Days and months', 'Name days and months; first short story.'),
(3, 'A1', 'Ordinals and telling time', 'Say dates and clock times.'),
(4, 'A1', 'sein and haben', 'Conjugate sein/haben and regular verbs.'),
(5, 'A1', 'Yes/no questions', 'Ask and answer simple questions.'),
(6, 'A1', 'Time prepositions', 'Use am/um/im with time expressions.'),
(7, 'A1', 'Cases and Nominativ', 'Understand what a case is; recognise Nominativ.'),
(8, 'A1', 'Akkusativ and its prepositions', 'Use Akkusativ after common prepositions.'),
(9, 'A1', 'Sentence structure', 'Build main clauses with correct verb position.'),
(10, 'A1', 'Consolidation I', 'Review weeks 1–9; re-read two class sheets.'),
(11, 'A1', 'Reading practice', 'Read longer A1 texts with a vocabulary list.'),
(12, 'A1', 'Second-source practice', 'Practise the same topics from a different textbook.'),
(13, 'A1', 'Everyday reading and extra units', 'Mix extra units with a real-world text.'),
(14, 'A1', 'A1 exam practice I', 'Complete one practice set under time limits.'),
(15, 'A1', 'A1 exam practice II', 'Targeted exam training on weak areas.'),
(16, 'A1', 'A1 review and gap week', 'Close gaps; decide if ready for A2.'),
(17, 'A2', 'Tenses overview', 'See present, perfect and preterite side by side.'),
(18, 'A2', 'Connectors', 'Join sentences with weil/dass/denn/aber.'),
(19, 'A2', 'Reflexive verbs', 'Use reflexive pronouns correctly.'),
(20, 'A2', 'als and wenn', 'Choose als vs wenn in subordinate clauses.'),
(21, 'A2', 'Genitiv', 'Recognise and form simple Genitiv phrases.'),
(22, 'A2', 'Comparison', 'Compare with Positiv/Komparativ/Superlativ.'),
(23, 'A2', 'Two-way prepositions', 'Choose Akkusativ/Dativ after Wechselpräpositionen.'),
(24, 'A2', 'Prepositions with verbs', 'Learn common verb + preposition pairs.'),
(25, 'A2', 'Relative clauses', 'Build relative clauses with the right pronoun.'),
(26, 'A2', 'Indirect questions', 'Report questions with ob and W-words.'),
(27, 'A2', 'Konjunktiv II', 'Polite requests and wishes.'),
(28, 'A2', 'Question articles', 'Use welcher/was für ein.'),
(29, 'A2', 'Second-source practice', 'Practise A2 topics from another coursebook.'),
(30, 'A2', 'Consolidation II', 'Review weeks 17–29; re-read class sheets.'),
(31, 'A2', 'A2 exam training', 'Practise exam task types.'),
(32, 'A2', 'A2 model test 1', 'Full timed model test.'),
(33, 'A2', 'A2 model test 2', 'Second model test and telc format.'),
(34, 'A2', 'A2 review and gap week', 'Close gaps; decide if ready for B1.'),
(35, 'B1', 'B1 kick-off: infinitive with zu', 'Form infinitive clauses with zu.'),
(36, 'B1', 'Past perfect', 'Use Plusquamperfekt in narration.'),
(37, 'B1', 'Connectors I', 'Master B1 connectors.'),
(38, 'B1', 'Paired connectors and je…desto', 'Use entweder…oder, sowohl…als auch, je…desto.'),
(39, 'B1', 'Genitive prepositions, n-declension', 'Handle wegen/trotz and n-nouns.'),
(40, 'B1', 'Passive with modal verbs; clause structure', 'Build passive and complex sentences.'),
(41, 'B1', 'Reading and phrases', 'Read B1 stories; collect set phrases.'),
(42, 'B1', 'Vocabulary building', 'Learn B1 vocabulary from two glossaries.'),
(43, 'B1', 'Coursebook progress', 'Steady coursebook work.'),
(44, 'B1', 'Coursebook progress', 'Steady coursebook work.'),
(45, 'B1', 'Review I', 'Re-read connector and tense sheets.'),
(46, 'B1', 'Coursebook progress', 'Steady coursebook work.'),
(47, 'B1', 'Speaking and writing phrases', 'Practise using Redemittel in your own sentences.'),
(48, 'B1', 'Coursebook progress', 'Steady coursebook work.'),
(49, 'B1', 'Review II', 'Re-read grammar sheets.'),
(50, 'B1', 'Vocabulary consolidation', 'Review all B1 words learned so far.'),
(51, 'B1', 'Coursebook progress', 'Steady coursebook work.'),
(52, 'B1', 'Year review and next plan', 'Review the year; decide how to extend the plan into B1 and B2.')
